implementation.content:
{
 "suite": "architecture",
 "datasetVersion": "1.0.0",
 "agent": "architect",
 "description": "20 golden tasks for the architect agent against AI-SDLC-frappe/sample-app/spice_lite, in Frappe and spice-platform terms (country apps, integration apps with required_apps, ERPNext as an external system, scheduler and queues, reports, permissions, site-per-country, patches, caching, API versioning). Matching is case-insensitive regex; an expected finding is covered when every group in `match` has at least one hit (AND of ORs). Severity is checked on the Findings-table row whose text hits the first group. Every factual trap carries `verify` evidence checked against the Frappe v15 source by `run-evals.mjs --verify-traps`.",
 "promptTemplate": "Evaluation run {{id}} (run_id eval-{{id}}, step 03). Do not create or edit any file: return your complete handoff as your final message.\n\nRequirement: {{requirement}}\n\nRead these files before answering: {{contextFiles}}.",
 "defaults": {
  "budget": {
   "maxTurns": 12,
   "maxCostUsd": 0.6
  },
  "minRecall": 0.75,
  "expectedStatus": [
   "complete",
   "needs-human"
  ]
 },
 "globalForbiddenClaims": [
  {
   "id": "G-ORM",
   "claim": "Invents a `frappe.orm` module (there is none; the data layer is frappe.get_list/get_doc, frappe.qb and frappe.db)",
   "patterns": [
    "\\bfrappe\\.orm\\b",
    "from frappe import orm\\b"
   ],
   "verify": [
    {
     "root": "frappe",
     "absent": "\\bfrappe\\.orm\\b",
     "why": "no module or attribute frappe.orm anywhere in the v15 source",
     "dir": "frappe",
     "ext": ".py"
    }
   ]
  },
  {
   "id": "G-SQLA",
   "claim": "Claims Frappe uses SQLAlchemy or the Django ORM (it uses its own DatabaseQuery and a PyPika fork, frappe.qb)",
   "patterns": [
    "\\b(uses|using|built on|based on|relies on|via|through)\\b[^.\\n]{0,25}\\b(SQLAlchemy|Django(?: ORM)?)\\b",
    "\\b(SQLAlchemy|Django ORM)\\b[^.\\n]{0,40}\\b(session|model|models|migration|queryset)s?\\b",
    "\\bmodels\\.Model\\b",
    "\\.objects\\.(filter|get|all)\\("
   ],
   "verify": [
    {
     "root": "frappe",
     "absent": "^\\s*(import|from)\\s+(sqlalchemy|django)\\b",
     "why": "no Python module in frappe/ imports sqlalchemy or django",
     "dir": "frappe",
     "ext": ".py"
    },
    {
     "root": "frappe",
     "absent": "sqlalchemy|SQLAlchemy|django|Django",
     "why": "pyproject.toml declares no SQLAlchemy or Django dependency",
     "file": "pyproject.toml"
    },
    {
     "root": "frappe",
     "file": "pyproject.toml",
     "present": "PyPika @ git\\+https://github\\.com/frappe/pypika",
     "why": "frappe.qb is Frappe's PyPika fork"
    }
   ]
  },
  {
   "id": "G-GETALL",
   "claim": "Claims frappe.get_all enforces or respects permissions (it is get_list with ignore_permissions=True)",
   "patterns": [
    "get_all\\b[^.\\n]{0,60}\\b(enforces|respects|applies|checks|honou?rs)\\b[^.\\n]{0,20}\\bpermission",
    "get_all\\b[^.\\n]{0,30}\\bis permission[- ]aware",
    "get_all\\b[^.\\n]{0,40}\\b(filters|restricts)\\b[^.\\n]{0,30}\\b(by|to) (the )?(user'?s? )?(roles|permissions)"
   ],
   "verify": [
    {
     "root": "frappe",
     "file": "frappe/__init__.py",
     "present": "def get_all\\(doctype, \\*args, \\*\\*kwargs\\):[\\s\\S]{0,1200}kwargs\\[\"ignore_permissions\"\\] = True",
     "why": "get_all sets ignore_permissions=True before calling get_list"
    }
   ]
  },
  {
   "id": "G-HOOKS",
   "claim": "Invents hooks.py keys (permission_hooks, scheduler_jobs, country_overrides, on_migrate, api_version do not exist)",
   "patterns": [
    "\\b(permission_hooks|scheduler_jobs|country_overrides|on_migrate|api_versions?)\\b"
   ],
   "verify": [
    {
     "root": "frappe",
     "absent": "\\b(permission_hooks|scheduler_jobs|country_overrides|on_migrate|api_versions?)\\b",
     "why": "no such key is read anywhere in frappe/ (real ones: permission_query_conditions, has_permission, scheduler_events, after_migrate, override_whitelisted_methods)",
     "dir": "frappe",
     "ext": ".py"
    }
   ]
  },
  {
   "id": "G-DRYRUN",
   "claim": "Recommends `bench migrate --dry-run` (the migrate command has only --skip-failing and --skip-search-index)",
   "patterns": [
    "migrate\\b[^\\n]{0,40}--dry-run",
    "--dry-run\\b[^\\n]{0,30}\\bmigrate\\b"
   ],
   "verify": [
    {
     "root": "frappe",
     "file": "frappe/commands/site.py",
     "present": "@click\\.command\\(\"migrate\"\\)\\n@click\\.option\\(\"--skip-failing\"[^\\n]*\\n@click\\.option\\(\"--skip-search-index\"[^\\n]*\\n@pass_context\\ndef migrate\\(",
     "why": "the migrate command is declared with exactly two options, neither of them --dry-run"
    }
   ]
  },
  {
   "id": "G-ITC",
   "claim": "Uses IntegrationTestCase or UnitTestCase, which do not exist in Frappe v15 (FrappeTestCase does)",
   "patterns": [
    "\\b(IntegrationTestCase|UnitTestCase)\\b"
   ],
   "verify": [
    {
     "root": "frappe",
     "absent": "\\b(IntegrationTestCase|UnitTestCase)\\b",
     "why": "v15 has frappe.tests.utils.FrappeTestCase only",
     "dir": "frappe",
     "ext": ".py"
    },
    {
     "root": "frappe",
     "file": "frappe/tests/utils.py",
     "present": "class FrappeTestCase\\(unittest\\.TestCase\\)",
     "why": "the v15 base class"
    }
   ]
  }
 ],
 "cases": [
  {
   "id": "ARCH-01",
   "title": "Kenya needs a national ID on SL Patient",
   "category": "design",
   "evalTypes": [
    "regression",
    "hallucination"
   ],
   "requirement": "The Kenya deployment must capture the patient's national ID (Huduma Namba) at registration, mandatory in Kenya only. Other countries run the same spice_lite code. Where should the field live and how does it ship?",
   "contextFiles": [
    "sample-app/spice_lite/spice_lite/clinical/doctype/sl_patient/sl_patient.json",
    "sample-app/spice_lite/spice_lite/hooks.py",
    "context/architecture/overview.md",
    "context/standards/frappe-coding-standards.md",
    "context/domain/spice-lite-glossary.md"
   ],
   "expectedFindings": [
    {
     "id": "F1",
     "concept": "A Custom Field in a Kenya country app, not a change to the core DocType",
     "match": [
      [
       "Custom Field"
      ],
      [
       "country app",
       "spice_ke",
       "Kenya app"
      ]
     ],
     "severity": null
    },
    {
     "id": "F2",
     "concept": "Editing sl_patient.json in spice_lite ships the Kenya field to every country deployment",
     "match": [
      [
       "sl_patient\\.json",
       "core DocType",
       "spice_lite DocType"
      ],
      [
       "every country",
       "all countries",
       "other countr",
       "every deployment",
       "all deployments"
      ]
     ],
     "severity": [
      "medium",
      "high"
     ]
    },
    {
     "id": "F3",
     "concept": "Ship it as a fixture filtered to the country app (fixtures + bench export-fixtures)",
     "match": [
      [
       "fixtures"
      ],
      [
       "export-fixtures",
       "filters",
       "\\\"dt\\\""
      ]
     ],
     "severity": null
    },
    {
     "id": "F4",
     "concept": "The national ID is PHI: never a document name, never logged",
     "match": [
      [
       "national[_ ]id",
       "Huduma"
      ],
      [
       "PHI"
      ]
     ],
     "severity": [
      "medium",
      "high"
     ]
    },
    {
     "id": "F5",
     "concept": "The country app declares required_apps = [\"spice_lite\"]",
     "match": [
      [
       "required_apps"
      ]
     ],
     "severity": null
    }
   ],
   "forbiddenClaims": [
    {
     "id": "C1",
     "claim": "Claims SL Patient already has a national ID field",
     "patterns": [
      "\\b(existing|already has|already contains|already stores)\\b[^.\\n]{0,40}\\bnational[_ ]id"
     ],
     "verify": [
      {
       "root": "repo",
       "absent": "national_id|huduma",
       "why": "no national ID field anywhere in spice_lite",
       "dir": "sample-app/spice_lite/spice_lite",
       "ext": ".json"
      },
      {
       "root": "repo",
       "absent": "national_id|huduma",
       "why": "no national ID in spice_lite Python either",
       "dir": "sample-app/spice_lite/spice_lite",
       "ext": ".py"
      }
     ]
    },
    {
     "id": "C2",
     "claim": "Recommends adding the Kenya field straight to the core sl_patient.json",
     "patterns": [
      "\\b(add|put|insert)\\b[^.\\n]{0,40}\\bnational[_ ]id\\b[^.\\n]{0,40}\\b(to|in|into)\\b[^.\\n]{0,10}sl_patient\\.json"
     ],
     "kind": "behaviour",
     "verify": []
    }
   ]
  },
  {
   "id": "ARCH-02",
   "title": "Telephony integration app with call-outcome logging and SMS reminders",
   "category": "design",
   "evalTypes": [
    "regression",
    "hallucination"
   ],
   "requirement": "Add a telephony integration: when a follow-up SL Encounter is created, place an automated reminder call or SMS through the national telco gateway and record the call outcome on the encounter. The telco API is slow (2-8 s) and rate limited.",
   "contextFiles": [
    "sample-app/spice_lite/spice_lite/hooks.py",
    "sample-app/spice_lite/spice_lite/clinical/doctype/sl_encounter/sl_encounter.json",
    "sample-app/spice_lite/spice_lite/clinical/doctype/sl_patient/sl_patient.json",
    "context/architecture/overview.md",
    "context/standards/frappe-coding-standards.md",
    "context/security/phi-and-secrets-policy.md"
   ],
   "expectedFindings": [
    {
     "id": "F1",
     "concept": "A separate integration app with required_apps = [\"spice_lite\"]",
     "match": [
      [
       "required_apps"
      ],
      [
       "spice_lite"
      ]
     ],
     "severity": null
    },
    {
     "id": "F2",
     "concept": "doc_events on SL Encounter in the integration app's hooks.py, not an edit of the core controller",
     "match": [
      [
       "doc_events"
      ],
      [
       "SL Encounter"
      ]
     ],
     "severity": null
    },
    {
     "id": "F3",
     "concept": "The telco call runs in a background job with an explicit queue, timeout and dedupe, after commit",
     "match": [
      [
       "frappe\\.enqueue",
       "background job"
      ],
      [
       "enqueue_after_commit",
       "job_id",
       "deduplicate",
       "timeout"
      ]
     ],
     "severity": null
    },
    {
     "id": "F4",
     "concept": "SL Patient has no phone field today; the integration must add one (Custom Field) or get consent data elsewhere",
     "match": [
      [
       "phone",
       "mobile"
      ],
      [
       "no (phone|mobile)",
       "does not have",
       "has no",
       "Custom Field",
       "missing"
      ]
     ],
     "severity": null
    },
    {
     "id": "F5",
     "concept": "Phone numbers are PHI and the SMS text must not carry clinical detail",
     "match": [
      [
       "PHI"
      ],
      [
       "SMS",
       "phone",
       "message text"
      ]
     ],
     "severity": [
      "medium",
      "high"
     ]
    }
   ],
   "forbiddenClaims": [
    {
     "id": "C1",
     "claim": "Claims SL Patient already stores a phone number",
     "patterns": [
      "\\b(existing|already has|already stores|already contains)\\b[^.\\n]{0,40}\\b(phone|mobile)"
     ],
     "verify": [
      {
       "root": "repo",
       "absent": "phone|mobile",
       "why": "no phone or mobile field in any spice_lite DocType",
       "dir": "sample-app/spice_lite/spice_lite",
       "ext": ".json"
      }
     ]
    },
    {
     "id": "C2",
     "claim": "Passes a retry count to frappe.enqueue (it has no retry parameter; extra kwargs go to the job function)",
     "patterns": [
      "enqueue\\([^)\\n]{0,160}\\b(retry|retries|max_retries)\\s*=",
      "\\b(retry|retries|max_retries)\\s*=\\s*\\d+[^.\\n]{0,40}\\bfrappe\\.enqueue"
     ],
     "verify": [
      {
       "root": "frappe",
       "absent": "def enqueue\\([^)]*\\b(retry|retries|max_retries)\\b",
       "why": "the enqueue signature has no retry parameter",
       "file": "frappe/utils/background_jobs.py"
      },
      {
       "root": "frappe",
       "file": "frappe/utils/background_jobs.py",
       "present": ":param kwargs: keyword arguments to be passed to the method",
       "why": "unknown kwargs are passed to the job, not to RQ"
      }
     ]
    }
   ]
  },
  {
   "id": "ARCH-03",
   "title": "Push finished encounters to the Ministry's ERPNext for billing",
   "category": "design",
   "evalTypes": [
    "regression",
    "hallucination"
   ],
   "requirement": "The Ministry runs ERPNext on its own server. Every finished SL Encounter must become a draft Sales Invoice there, exactly once, within an hour.",
   "contextFiles": [
    "sample-app/spice_lite/spice_lite/hooks.py",
    "sample-app/spice_lite/spice_lite/clinical/doctype/sl_encounter/sl_encounter.json",
    "context/architecture/overview.md",
    "context/security/phi-and-secrets-policy.md",
    "context/standards/api-standards.md"
   ],
   "expectedFindings": [
    {
     "id": "F1",
     "concept": "ERPNext is an external system reached over its REST API with a dedicated integration user's API key and secret",
     "match": [
      [
       "ERPNext"
      ],
      [
       "REST",
       "/api/resource",
       "API key",
       "token "
      ]
     ],
     "severity": null
    },
    {
     "id": "F2",
     "concept": "Do not install ERPNext on the clinical site; build a connector integration app",
     "match": [
      [
       "ERPNext"
      ],
      [
       "own server",
       "separate (site|server|instance)",
       "external",
       "not (be )?install",
       "integration app"
      ]
     ],
     "severity": null
    },
    {
     "id": "F3",
     "concept": "Exactly once needs idempotency: a sync record or external id, and a dedupe job_id",
     "match": [
      [
       "idempoten",
       "exactly once",
       "duplicate invoice"
      ],
      [
       "sync",
       "external id",
       "job_id",
       "deduplicate",
       "custom field"
      ]
     ],
     "severity": [
      "medium",
      "high"
     ]
    },
    {
     "id": "F4",
     "concept": "Send the minimum: an opaque patient reference, not MRN or name, to the billing system",
     "match": [
      [
       "PHI"
      ],
      [
       "ERPNext",
       "billing",
       "invoice"
      ],
      [
       "minim",
       "pseudonym",
       "opaque",
       "SLP-",
       "document name",
       "no MRN",
       "not the MRN"
      ]
     ],
     "severity": [
      "high",
      "critical"
     ]
    },
    {
     "id": "F5",
     "concept": "Run the push from a background job (long or default queue, explicit timeout), not in on_update",
     "match": [
      [
       "frappe\\.enqueue",
       "background",
       "scheduler"
      ],
      [
       "long",
       "timeout",
       "queue"
      ]
     ],
     "severity": null
    }
   ],
   "forbiddenClaims": [
    {
     "id": "C1",
     "claim": "Claims spice_lite already depends on or integrates with ERPNext",
     "patterns": [
      "\\b(already|currently)\\b[^.\\n]{0,30}\\b(depends on|integrates with|requires|installs|uses) ERPNext",
      "spice_lite\\b[^.\\n]{0,40}\\brequired_apps\\b[^.\\n]{0,30}erpnext"
     ],
     "verify": [
      {
       "root": "repo",
       "absent": "erpnext",
       "why": "spice_lite's hooks.py has required_apps = [] and never mentions ERPNext",
       "file": "sample-app/spice_lite/spice_lite/hooks.py"
      }
     ]
    },
    {
     "id": "C2",
     "claim": "Calls ERPNext DocTypes on the clinical site with frappe.get_doc (ERPNext is not installed there)",
     "patterns": [
      "frappe\\.(get_doc|new_doc|get_list)\\(\\s*[\\\"'](Sales Invoice|Customer|Item)[\\\"']"
     ],
     "verify": [
      {
       "root": "frappe",
       "absent": "\\\"(Sales Invoice|Customer)\\\"",
       "why": "no Sales Invoice or Customer DocType in frappe or spice_lite: they belong to ERPNext",
       "dir": "frappe",
       "ext": ".json"
      }
     ]
    }
   ]
  },
  {
   "id": "ARCH-04",
   "title": "Nightly job: mark long-inactive patients inactive",
   "category": "performance",
   "evalTypes": [
    "regression",
    "hallucination"
   ],
   "requirement": "Every night, set active = 0 on SL Patients with no SL Encounter in the last 24 months. The Kenya deployment has about 2 million patients.",
   "contextFiles": [
    "sample-app/spice_lite/spice_lite/hooks.py",
    "sample-app/spice_lite/spice_lite/clinical/doctype/sl_patient/sl_patient.json",
    "sample-app/spice_lite/spice_lite/clinical/doctype/sl_encounter/sl_encounter.json",
    "context/standards/frappe-coding-standards.md",
    "sample-app/spice_lite/spice_lite/clinical/doctype/sl_patient/sl_patient.py"
   ],
   "expectedFindings": [
    {
     "id": "F1",
     "concept": "Register it in scheduler_events as daily_long (long queue) or a cron entry",
     "match": [
      [
       "scheduler_events"
      ],
      [
       "daily_long",
       "long queue",
       "cron",
       "1500"
      ]
     ],
     "severity": null
    },
    {
     "id": "F2",
     "concept": "A plain daily job runs on the default queue with a 300 s timeout",
     "match": [
      [
       "300"
      ],
      [
       "timeout"
      ]
     ],
     "severity": [
      "medium",
      "high"
     ]
    },
    {
     "id": "F3",
     "concept": "Set-based update in chunks, not get_doc().save() per patient",
     "match": [
      [
       "set-based",
       "frappe\\.qb\\.update",
       "chunk",
       "batch"
      ],
      [
       "get_doc",
       "save\\(\\)",
       "per patient",
       "per-patient",
       "loop"
      ]
     ],
     "severity": [
      "high",
      "medium"
     ]
    },
    {
     "id": "F4",
     "concept": "SL Encounter.encounter_date has no index; the 24-month lookup needs one",
     "match": [
      [
       "encounter_date"
      ],
      [
       "index",
       "search_index"
      ]
     ],
     "severity": [
      "medium",
      "high"
     ]
    },
    {
     "id": "F5",
     "concept": "A qb update skips validate/on_update, so no audit line or Version; record a summary",
     "match": [
      [
       "on_update",
       "log_access",
       "audit",
       "Version"
      ],
      [
       "skip",
       "bypass",
       "not run",
       "no audit",
       "does not run"
      ]
     ],
     "severity": [
      "low",
      "medium"
     ]
    }
   ],
   "mustNotExist": [
    "sample-app/spice_lite/spice_lite/tasks.py"
   ],
   "forbiddenClaims": [
    {
     "id": "C1",
     "claim": "Claims spice_lite already has a scheduled job (hooks.py only has a commented-out example)",
     "patterns": [
      "\\b(existing|current|already (configured|scheduled|registered|defined))\\b[^.\\n]{0,40}\\b(scheduler_events|scheduled job|daily job|spice_lite\\.tasks)",
      "spice_lite\\.tasks\\.daily\\b[^.\\n]{0,40}\\b(already|existing|currently|runs)\\b"
     ],
     "verify": [
      {
       "root": "repo",
       "absent": "^scheduler_events\\s*=",
       "why": "the only scheduler_events line in hooks.py is a comment",
       "file": "sample-app/spice_lite/spice_lite/hooks.py"
      }
     ]
    },
    {
     "id": "C2",
     "claim": "Claims plain daily events already run on the long queue",
     "patterns": [
      "\\bdaily\\b[^.\\n]{0,40}\\b(events?|jobs?)\\b[^.\\n]{0,40}\\b(run|runs|go|goes|are queued) on the long queue"
     ],
     "verify": [
      {
       "root": "frappe",
       "file": "frappe/core/doctype/scheduled_job_type/scheduled_job_type.py",
       "present": "return \"long\" if \\(\"Long\" in self\\.frequency or \"Maintenance\" in self\\.frequency\\) else \"default\"",
       "why": "only *_long and maintenance frequencies use the long queue"
      }
     ]
    }
   ]
  },
  {
   "id": "ARCH-05",
   "title": "Hypertension register report over 500k observations",
   "category": "performance",
   "evalTypes": [
    "regression",
    "hallucination"
   ],
   "requirement": "Add a Script Report \"Hypertension Register\": every patient whose latest systolic BP (LOINC 8480-6) in the last 90 days is above 140, grouped by country. SL Observation has about 500,000 rows per deployment.",
   "contextFiles": [
    "sample-app/spice_lite/spice_lite/clinical/doctype/sl_observation/sl_observation.json",
    "sample-app/spice_lite/spice_lite/clinical/doctype/sl_patient/sl_patient.json",
    "sample-app/spice_lite/spice_lite/api/fhir.py",
    "context/standards/frappe-coding-standards.md",
    "context/security/phi-and-secrets-policy.md"
   ],
   "expectedFindings": [
